#!/usr/bin/env node
// Dev-start guard: makes the classic Prisma trap impossible to miss.
//
// A generated Prisma client can exist yet be stale (generated by another
// Prisma version or an older schema). The app then boots fine but every
// database route fails with the opaque P6001 error ("the URL must start
// with the protocol prisma://") — hit in local dev on 2026-11-14, fixed
// then by a manual `prisma generate`. This guard runs before `npm run
// dev` (root dev / dev:web / dev:realtime): when the client fingerprint
// (schema + Prisma versions, see ensure-prisma.mjs) is missing or stale
// it regenerates automatically; when regeneration is impossible it stops
// with a clear Vietnamese explanation instead of letting the app boot
// into a wall of 500s.
import fs from "node:fs";
import path from "node:path";
import {
  ROOT,
  prismaClientIsFresh,
  runPrismaGenerate,
  stampPrismaClient,
} from "./ensure-prisma.mjs";

const depsInstalled =
  fs.existsSync(path.join(ROOT, "node_modules/prisma/package.json")) &&
  fs.existsSync(path.join(ROOT, "node_modules/@prisma/client/package.json"));

if (!depsInstalled) {
  console.error(
    "[prisma-guard] Chưa cài dependencies (không thấy node_modules/prisma).\n" +
      "Hãy chạy `npm install` ở thư mục gốc dự án trước, rồi chạy lại `npm run dev`."
  );
  process.exit(1);
}

if (prismaClientIsFresh(ROOT)) {
  process.exit(0);
}

console.log(
  "[prisma-guard] Prisma Client đang lệch phiên bản/schema (hoặc chưa có dấu kiểm chứng) — đang generate lại…"
);
const ok = runPrismaGenerate(ROOT);
if (!ok) {
  console.error(
    "[prisma-guard] KHÔNG generate được Prisma Client (thường do mạng chặn tải engine từ binaries.prisma.sh).\n" +
      "Cách xử lý thủ công: kiểm tra mạng rồi chạy `npm run db:generate` ở thư mục gốc dự án.\n" +
      "Nếu cứ khởi động app lúc này, mọi API chạm database sẽ lỗi 500 (P6001) — hãy generate thành công trước."
  );
  process.exit(1);
}
stampPrismaClient(ROOT);
console.log("[prisma-guard] Xong — Prisma Client đã khớp schema và phiên bản Prisma hiện tại.");
